// OTOMATİK ÜRETİLİR (_tasarim/araclar/hikaye-gom.py) — elle düzenleme. GPT 2340 teslimi: kral portreleri, dört hikâye karesi
// (köprü, yemin, bozulan mühür, şafakta karşılaşma) ve Diyar Haritası. WebP base64; ilk kullanımda Blob URL.
const D = {
"volgar":"",
"edran":"",
"yemin-1":"",
"yemin-2":"",
"yemin-3":"",
"yemin-4":"",
"diyar":"",
};
const U = {};
export const url = k => { if (U[k]) return U[k]; const s = D[k]; if (!s) return null;
  try { const b = atob(s), a = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i); return (U[k] = URL.createObjectURL(new Blob([a], { type: 'image/webp' }))); }
  catch { return (U[k] = 'data:image/webp;base64,' + s); } };
